-- tier: container
CREATE EXTENSION IF NOT EXISTS plv8;
-- tier: any
-- Run again on a database it built, as each release runs it, this replaces the
-- machine's code and keeps its instances: its tables keep the shape they were
-- made with, and each instance the protocol it was made under. A new protocol
-- is a migration's to carry them forward, refused here rather than half applied.
DO $protocol$ BEGIN
  IF to_regnamespace('hybrid_compute_batch') IS NOT NULL AND obj_description(to_regnamespace('hybrid_compute_batch'), 'pg_namespace') IS DISTINCT FROM 'Hybrid compute_batch protocol 1; no public canonical-state access' THEN
    RAISE EXCEPTION 'hybrid_compute_batch holds instances of another protocol than 1' USING ERRCODE = '55000';
  END IF;
END $protocol$;
CREATE SCHEMA IF NOT EXISTS hybrid_compute_batch;
REVOKE ALL ON SCHEMA hybrid_compute_batch FROM PUBLIC;
-- Durable publication and its receipt share the caller's serializable transaction.
CREATE OR REPLACE FUNCTION hybrid_compute_batch.serial() RETURNS void LANGUAGE plpgsql AS $serial$
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'a compute_batch step runs serializable, not %', current_setting('transaction_isolation') USING ERRCODE = '25000';
  END IF;
END;
$serial$;
-- A player's lock, the same in every machine's schema: an advisory lock held
-- to the end of the transaction, keyed by the player and taken in key order,
-- so two steps holding several never wait on each other's. One call takes a
-- step's whole set: a second would take its keys out of order.
CREATE OR REPLACE FUNCTION hybrid_compute_batch.hold(actors uuid[]) RETURNS void LANGUAGE plpgsql AS $hold$
DECLARE k integer;
BEGIN
  FOR k IN SELECT DISTINCT hashtext(a::text) FROM unnest(actors) a WHERE a IS NOT NULL ORDER BY 1 LOOP
    PERFORM pg_advisory_xact_lock(hashtext('mecha player'), k);
  END LOOP;
END;
$hold$;
REVOKE ALL ON FUNCTION hybrid_compute_batch.hold(uuid[]) FROM PUBLIC;
-- An instance's players, and one about to join it.
CREATE OR REPLACE FUNCTION hybrid_compute_batch.hold_instance(room uuid, joining uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $hold_instance$
BEGIN
  PERFORM hybrid_compute_batch.hold(ARRAY(SELECT m.actor FROM hybrid_compute_batch.member m WHERE m.instance_id = room) || joining);
END;
$hold_instance$;
REVOKE ALL ON FUNCTION hybrid_compute_batch.hold_instance(uuid, uuid) FROM PUBLIC;
-- A step's time: the transaction's, the same on every read in it, so every
-- check in one step agrees on it, and no session can set it. A step a timer
-- delivers is given the tick's time instead (dispatch's at), so a deadline
-- is decided on the ticker's clock alone.
CREATE OR REPLACE FUNCTION hybrid_compute_batch.clock() RETURNS bigint LANGUAGE sql STABLE AS $clock$
SELECT floor(extract(epoch FROM transaction_timestamp()) * 1000)::bigint;
$clock$;
REVOKE ALL ON FUNCTION hybrid_compute_batch.clock() FROM PUBLIC;
CREATE TABLE IF NOT EXISTS hybrid_compute_batch.instance (
  id uuid PRIMARY KEY,
  version integer NOT NULL CHECK (version = 1),
  revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
  state jsonb NOT NULL
);
CREATE TABLE IF NOT EXISTS hybrid_compute_batch.member (
  instance_id uuid NOT NULL REFERENCES hybrid_compute_batch.instance,
  actor uuid NOT NULL,
  seat text NOT NULL,
  PRIMARY KEY(instance_id, actor), UNIQUE(instance_id, seat)
);
-- An actor's seats across instances (an admission asks whether one sits elsewhere),
-- read by index so a step locks that actor's rows and no one else's.
CREATE INDEX IF NOT EXISTS member_actor ON hybrid_compute_batch.member (actor);
CREATE TABLE IF NOT EXISTS hybrid_compute_batch.receipt (
  instance_id uuid NOT NULL REFERENCES hybrid_compute_batch.instance,
  actor uuid NOT NULL,
  command_id text NOT NULL,
  request jsonb NOT NULL,
  result jsonb NOT NULL,
  -- What the step was given beside its request, so it replays.
  now bigint NOT NULL,
  entropy text,
  PRIMARY KEY(instance_id, actor, command_id)
);
