$hybrid$;
REVOKE ALL ON FUNCTION hybrid_compute_batch.engine(jsonb) FROM PUBLIC;
-- tier: any
CREATE OR REPLACE FUNCTION hybrid_compute_batch.step(input jsonb) RETURNS jsonb LANGUAGE plpgsql AS $step$
BEGIN RETURN hybrid_compute_batch.engine(input); END;
$step$;
REVOKE ALL ON FUNCTION hybrid_compute_batch.step(jsonb) FROM PUBLIC;



CREATE OR REPLACE FUNCTION hybrid_compute_batch.dispatch(instance_id uuid, actor uuid, command_id text, request jsonb, tier text, at bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, hybrid_compute_batch
SET statement_timeout = '5s'
SET lock_timeout = '2s'
AS $dispatch$
DECLARE
  game hybrid_compute_batch.instance;
  prior hybrid_compute_batch.receipt;
  seat text;
  answer jsonb;
  reduced jsonb;
  recipients jsonb;
  now_ms bigint;
  drawn text;
  prepared_revision bigint;
BEGIN
  PERFORM hybrid_compute_batch.serial();
  PERFORM hybrid_compute_batch.hold_instance(instance_id);

  SELECT * INTO STRICT game FROM hybrid_compute_batch.instance i WHERE i.id = instance_id FOR UPDATE;
  IF tier = 'omnishell' THEN
    SELECT m.seat INTO seat FROM hybrid_compute_batch.member m WHERE m.instance_id = game.id AND m.actor = dispatch.actor;
    IF seat IS NULL THEN RAISE EXCEPTION 'not a member' USING ERRCODE = '42501'; END IF;
  ELSIF tier <> 'mecha' THEN
    RAISE EXCEPTION 'invalid tier';
  END IF;
  now_ms := coalesce(at, hybrid_compute_batch.clock());
  SELECT * INTO prior FROM hybrid_compute_batch.receipt r WHERE r.instance_id = game.id AND r.actor = dispatch.actor AND r.command_id = dispatch.command_id;
  IF FOUND THEN
    IF prior.request <> request THEN RAISE EXCEPTION 'command id reused with different input' USING ERRCODE = '22023'; END IF;
    RETURN prior.result;
  END IF;
  IF request->>'version' IS DISTINCT FROM game.version::text THEN
    answer := jsonb_build_object('kind', 'rejected', 'reason', 'protocol_version');
  ELSIF request->>'expected_revision' IS DISTINCT FROM game.revision::text THEN
    answer := jsonb_build_object('kind', 'rejected', 'reason', 'stale_revision');
  ELSE

    SELECT coalesce(jsonb_agg(m.seat ORDER BY m.seat), '[]'::jsonb) INTO recipients FROM hybrid_compute_batch.member m WHERE m.instance_id = game.id;
    reduced := hybrid_compute_batch.step(jsonb_build_object(
      'state', game.state,
      'event', request->'event',
      'context', jsonb_build_object('actor', seat, 'tier', tier, 'now', now_ms),
      'viewers', recipients
    ));
    IF reduced->>'kind' = 'accepted' THEN
      IF game.state->>'phase' = 'active' THEN
        DECLARE next_reduced jsonb := reduced; invocation_key text;
        BEGIN
          reduced := jsonb_build_object('state', game.state);
          invocation_key := ('compute:' || (reduced->'state'->>'name') || ':' || (reduced->'state'->>'wake'))::text;
          reduced := next_reduced;
          IF reduced->'state'->>'phase' = 'active' AND invocation_key IS DISTINCT FROM ('compute:' || (reduced->'state'->>'name') || ':' || (reduced->'state'->>'wake'))::text THEN
            RAISE EXCEPTION 'Cortex invocation % retains its key until settlement', 'active' USING ERRCODE = 'check_violation';
          END IF;
          IF request->'event'->>'kind' IN ('complete', 'supersede') AND NOT EXISTS (
            SELECT FROM durex.work work
            WHERE work.key = invocation_key
              AND work.task = 'compute_batch'
              AND work.machine = 'compute_batch'
              AND work.instance = game.id
              AND work.outcome->'payload' = request->'event'->'payload'
              AND ((work.outcome->>'kind' = 'done' AND work.done_event = request->'event'->>'kind')
                OR (work.outcome->>'kind' = 'failed' AND work.failed_event = request->'event'->>'kind'))
          ) THEN
            RAISE EXCEPTION 'Cortex invocation % requires its recorded outcome', 'active' USING ERRCODE = 'check_violation';
          END IF;
        END;
      END IF;
      IF game.state->>'phase' = 'idle' AND request->'event'->>'kind' = 'schedule' THEN
      IF (compute.ready(game.id)) IS NOT TRUE THEN
        reduced := jsonb_build_object('kind', 'rejected', 'reason', 'prerequisite_pending');
      ELSE

      END IF;
    END IF;
IF game.state->>'phase' = 'active' AND request->'event'->>'kind' = 'claim' THEN
      IF (compute.ready(game.id)) IS NOT TRUE THEN
        reduced := jsonb_build_object('kind', 'rejected', 'reason', 'prerequisite_pending');
      ELSE

      END IF;
    END IF;
    END IF;
    IF reduced->>'kind' = 'accepted' THEN
      UPDATE hybrid_compute_batch.instance i SET state = reduced->'state', revision = i.revision + 1 WHERE i.id = game.id
        RETURNING i.revision INTO STRICT game.revision;
      IF reduced->'state'->>'phase' = 'active' AND game.state->>'phase' IS DISTINCT FROM 'active' THEN
        IF EXISTS (SELECT FROM durex.work work WHERE work.key = ('compute:' || (reduced->'state'->>'name') || ':' || (reduced->'state'->>'wake'))::text) THEN
          RAISE EXCEPTION 'Cortex invocation % requires a fresh key', 'active' USING ERRCODE = 'unique_violation';
        END IF;
        PERFORM durex.enqueue_work('compute_batch', ('compute:' || (reduced->'state'->>'name') || ':' || (reduced->'state'->>'wake'))::text, (jsonb_build_object('name', reduced->'state'->>'name', 'wake', reduced->'state'->>'wake'))::jsonb,
          'compute_batch', game.id, 'complete', 'supersede',
          (to_timestamp((reduced->'state'->>'due')::double precision / 1000))::timestamptz, ((reduced->'state'->>'attempts')::integer)::integer);
      END IF;
      game.state := reduced->'state';

      answer := jsonb_build_object('kind', 'accepted');
    ELSIF reduced->>'kind' = 'rejected' THEN
      answer := reduced;
    ELSE
      RAISE EXCEPTION 'invalid hybrid result';
    END IF;
  END IF;
  answer := answer || jsonb_build_object('command_id', command_id, 'revision', game.revision::text);
  INSERT INTO hybrid_compute_batch.receipt (instance_id, actor, command_id, request, result, now, entropy)
    VALUES (game.id, actor, command_id, request, answer, now_ms, drawn);
  RETURN answer;
END;
$dispatch$;
REVOKE ALL ON FUNCTION hybrid_compute_batch.dispatch(uuid, uuid, text, jsonb, text, bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION hybrid_compute_batch.deliver(instance_id uuid, event jsonb, at bigint DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_compute_batch AS $deliver$
DECLARE revision bigint; answer jsonb;
BEGIN
  -- Locked as dispatch will lock it, so the revision read is the one it checks.
  PERFORM hybrid_compute_batch.hold_instance(instance_id);
  SELECT i.revision INTO STRICT revision FROM hybrid_compute_batch.instance i WHERE i.id = instance_id FOR UPDATE;
  -- One delivery is accepted per revision, so the revision names it.
  answer := hybrid_compute_batch.dispatch(instance_id, '00000000-0000-0000-0000-000000000000', 'mecha/' || revision::text,
    jsonb_build_object('version', 1, 'expected_revision', revision::text, 'event', event), 'mecha', at);
  IF answer->>'kind' IS DISTINCT FROM 'accepted' THEN
    RAISE EXCEPTION 'Mecha delivery refused: %', answer USING ERRCODE = 'check_violation';
  END IF;
END;
$deliver$;
REVOKE ALL ON FUNCTION hybrid_compute_batch.deliver(uuid, jsonb, bigint) FROM PUBLIC;



DO $private$
DECLARE relation record; grant_ record;
BEGIN
  FOR relation IN
    SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'hybrid_compute_batch' AND c.relkind IN ('r', 'p')
  LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', 'hybrid_compute_batch', relation.relname);
  END LOOP;
  FOR grant_ IN
    SELECT DISTINCT 'SCHEMA' AS kind, quote_ident(n.nspname) AS name, a.grantee
      FROM pg_namespace n, aclexplode(coalesce(n.nspacl, acldefault('n', n.nspowner))) a
      WHERE n.nspname = 'hybrid_compute_batch' AND a.grantee <> n.nspowner
    UNION
    SELECT DISTINCT 'TABLE', format('%I.%I', n.nspname, c.relname), a.grantee
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace,
        aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
      WHERE n.nspname = 'hybrid_compute_batch' AND c.relkind IN ('r', 'p', 'v', 'm', 'f') AND a.grantee <> c.relowner
    UNION
    SELECT DISTINCT 'FUNCTION', p.oid::regprocedure::text, a.grantee
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace,
        aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
      WHERE n.nspname = 'hybrid_compute_batch' AND a.grantee <> p.proowner
  LOOP
    EXECUTE format('REVOKE ALL ON %s %s FROM %s', grant_.kind, grant_.name,
      CASE WHEN grant_.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(grant_.grantee)) END);
  END LOOP;
END;
$private$;

COMMENT ON SCHEMA hybrid_compute_batch IS 'Hybrid compute_batch protocol 1; no public canonical-state access';
